contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address[] calldata accs, uint256[] calldata ids) public {
        require(accs.length != ids.length);
        require(accs.length > 0);

        bool revertedMismatch;
        try c.balanceOfBatch(accs, ids) {
            revertedMismatch = false;
        } catch {
            revertedMismatch = true;
        }

        uint256 n = accs.length;
        address[] memory accs2 = new address[](n);
        uint256[] memory ids2 = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            accs2[i] = accs[i];
            ids2[i] = ids[i];
        }

        bool revertedMatch;
        uint256[] memory balances;
        try c.balanceOfBatch(accs2, ids2) returns (uint256[] memory b) {
            revertedMatch = false;
            balances = b;
        } catch {
            revertedMatch = true;
        }

        bool allZero = true;
        for (uint256 i = 0; i < n; i++) {
            if (balances[i] != 0) {
                allZero = false;
            }
        }

        assert(revertedMismatch && !revertedMatch && balances.length == n && allZero);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address operator) public {
        require(operator != address(this));

        // self-approval must revert
        bool revertedSelf;
        try c.setApprovalForAll(address(this), address(this)) {
            revertedSelf = false;
        } catch {
            revertedSelf = true;
        }

        // approve a distinct operator
        c.setApprovalForAll(operator, true);
        bool approvedAfterTrue = c.isApprovedForAll(address(this), operator);

        // revoke the operator
        c.setApprovalForAll(operator, false);
        bool approvedAfterFalse = c.isApprovedForAll(address(this), operator);

        assert(revertedSelf && approvedAfterTrue && !approvedAfterFalse);
    }

    receive() external payable {}
}

