contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        string memory name_,
        string memory tokenURI,
        bool finiteSupply,
        bool transferable,
        uint256 itemsRemaining,
        uint256 itemPrice,
        uint16 dailyAllowance
    ) public payable {
        require(bytes(tokenURI).length > 0);

        uint256 countBefore = c.uniqueTokensOutstanding();
        uint256 tokenId = countBefore;

        c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);

        uint256 countAfter = c.uniqueTokensOutstanding();
        uint256 remaining = c.remainingSupply(tokenId);
        string memory uriRet = c.uri(tokenId);

        assert(
            countAfter == countBefore + 1 &&
            remaining == itemsRemaining &&
            keccak256(bytes(uriRet)) == keccak256(bytes(tokenURI))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        string memory name_,
        string memory tokenURI,
        bool finiteSupply,
        bool transferable,
        uint256 itemsRemaining,
        uint256 itemPrice,
        uint16 dailyAllowance
    ) public payable {
        require(itemsRemaining > 0);
        require(itemPrice > 0);

        uint256 tokenId = c.uniqueTokensOutstanding();
        c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);

        bool reverted;
        try c.safeTransferFrom(address(this), address(this), tokenId, 1, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address self, bool approved) public payable {
        require(self == address(this));
        bool reverted;
        try c.setApprovalForAll(self, approved) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && !c.isApprovedForAll(self, self));
    }
    receive() external payable {}
}

